+    #[test]
+    fn is_provider_data_only_cases() {
+        assert!(!assistant(vec![]).is_provider_data_only());
+        assert!(assistant(vec![pd()]).is_provider_data_only());
+        assert!(
+            !assistant(vec![ContentPart::Text { text: "a".into() }, pd()]).is_provider_data_only()
