+            let Some(json) = line.strip_prefix("data: ") else {
+                continue;
+            };
+            let chunk: GeminiChunk = serde_json::from_str(json).unwrap();
+            events.extend(translator.consume(chunk).into_iter().map(Result::unwrap));
+        }
