+            "dummy signature in {text}"
+        );
+        let calls: Vec<&Value> = body["contents"]
+            .as_array()
+            .unwrap()
+            .iter()
+            .flat_map(|c| c["parts"].as_array().unwrap().iter())
+            .filter(|p| p.get("functionCall").is_some())
+            .collect();
+        let names: Vec<&str> = calls
+            .iter()
+            .map(|p| p["functionCall"]["name"].as_str().unwrap())
