+        assert_eq!(calls[0]["thoughtSignature"], json!("SIG_A"), "{body}");
+        assert!(calls[1].get("thoughtSignature").is_none(), "{body}");
+        assert!(calls[2].get("thoughtSignature").is_none(), "{body}");
+    }
