                // stopped value, so it reports as completed with the run usage.
                AgentEvent::RunStopped { usage: u, .. } => {
                    status = RunStatus::Completed;
                    run_usage = Some(*u);
                }
                AgentEvent::RunFailed { error: e } => {
                    status = RunStatus::Failed;
                    error = Some(e.clone());
